export { };


declare global {

    interface Window {

        craftale: {

            /*
            |--------------------------------------------------------------------------
            | Application
            |--------------------------------------------------------------------------
            */

            app: {

                name: string;

                version: string;

            };


            /*
            |--------------------------------------------------------------------------
            | Filesystem
            |--------------------------------------------------------------------------
            */

            filesystem: {


                /*
                |--------------------------------------------------------------------------
                | Select Folder
                |--------------------------------------------------------------------------
                */

                selectFolder(): Promise<
                    string | null
                >;


                /*
                |--------------------------------------------------------------------------
                | Read Directory
                |--------------------------------------------------------------------------
                */

                readDirectory(
                    directoryPath: string
                ): Promise<
                    Array<{
                        name: string;

                        path: string;

                        type:
                        | "file"
                        | "directory";
                    }>
                >;


                /*
                |--------------------------------------------------------------------------
                | Read File
                |--------------------------------------------------------------------------
                */

                readFile(
                    filePath: string
                ): Promise<string>;

            };

        };

    };

}